package com.backend.nutri_predic.consumo.dto; import com.backend.nutri_predic.consumo.entity.DetalleEvaluacionConsumo; import java.math.BigDecimal; public record DetalleEvaluacionConsumoResponse(Long criterioEvaluadoId,String componente,String fuente,BigDecimal cantidadObservada,BigDecimal referenciaAplicada,BigDecimal referenciaAplicadaHasta,String unidad,String operador,String resultado,String motivoNoCalculable){public static DetalleEvaluacionConsumoResponse from(DetalleEvaluacionConsumo d){return new DetalleEvaluacionConsumoResponse(d.getCriterioEvaluadoId(),d.getComponente(),d.getFuente(),d.getCantidadObservada(),d.getReferenciaAplicada(),d.getReferenciaAplicadaHasta(),d.getUnidad(),d.getOperador(),d.getResultado(),d.getMotivoNoCalculable());}}
